var o=`1054-char-kway-teow`;var a=`world-1054`;var t=`MY`;var n=`southeast-asia`;var s=4;var r=46;var d={en:`Char Kway Teow`,ua:`Чар квай теоу`};var l={en:`Char Kway Teow is a dish from Malaysia prepared with rice noodles, garlic, shrimp, smoked pork loin. This is a home-scale version with measured ingredients in the individual steps where they are used. Smoked pork loin stands in for Chinese lap cheong; use flat rice noodles if available.`,ua:`Чар квай теоу, страва кухні країни Малайзія, яку готують із таких продуктів: рисова локшина, часник, креветка, копчена свиняча корейка. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Копчена корейка замінює китайську ковбасу лап чонг; бажано використовувати широку плоску рисову локшину.`};var u=[{en:`Soak the measured rice or noodles in clean cool water for about 25 minutes, then drain and proceed to the specified cooking step.`,ua:`Замочіть зазначені рис або локшину в чистій прохолодній воді близько 25 хвилин, злийте і переходьте до подальшого готування.`,t:[`soaking-dried-produce`],m:25,i:[[`rice-noodles`,420,`g`],[`water`,900,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`garlic`,5,`clove`],[`canola-oil`,45,`ml`],[`shrimp`,300,`g`],[`smoked-pork-loin`,120,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`light-soy-sauce`,35,`ml`],[`dark-soy-sauce`,22,`ml`],[`mung-bean-sprouts`,220,`g`],[`chives`,80,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 4 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 4 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:4,i:[[`chicken-egg`,3,`pcs`]]}];var h={slug:o,id:a,country:`MY`,region:n,servings:4,minutes:46,title:d,text:l,steps:u};export{t as country,h as default,a as id,r as minutes,n as region,s as servings,o as slug,u as steps,l as text,d as title};